<template>
  <div class="commercial-page">
    <section class="commercial-hero operations-hero"><div><span class="eyebrow">PLATFORM OPERATIONS</span><h2>平台运营控制台</h2><p>使用独立平台凭据查看租户、资源、告警与服务健康；企业令牌不能访问此页面数据。</p></div><div class="service-health" :class="health?.status.toLowerCase()"><span/><div><strong>{{health?.status??'CHECKING'}}</strong><small>{{health?.serviceName??'AI BI API'}} · {{health?formatTime(health.checkedAt):'正在检查'}}</small></div></div></section>
    <section v-if="!overview" class="platform-auth-card"><div class="platform-lock"><el-icon><Key /></el-icon></div><h3>平台级身份验证</h3><p>请输入平台运营令牌。令牌仅保存在当前页面内存，刷新或离开页面即清除。</p><el-input v-model="platformToken" type="password" show-password placeholder="X-Platform-Token" @keyup.enter="loadOverview" /><el-button type="primary" :loading="loading" :disabled="!platformToken.trim()" @click="loadOverview">进入运营控制台</el-button><el-alert v-if="error" type="error" :title="error" :closable="false" /></section>
    <template v-else><div class="operations-toolbar"><span>平台数据来自受保护的 `/platform/overview` 接口。</span><el-button @click="clearToken">退出平台视图</el-button><el-button type="primary" :loading="loading" @click="loadOverview">刷新</el-button></div><section class="operations-metric-grid"><article><span>活跃租户</span><strong>{{overview.activeTenants}}</strong><small>当前有效企业范围</small></article><article><span>有效订阅</span><strong>{{overview.activeSubscriptions}}</strong><small>商业订阅服务</small></article><article><span>已支付订单</span><strong>{{overview.paidOrders}}</strong><small>服务端签名确认</small></article><article :class="{danger:overview.openAlerts>0}"><span>开放告警</span><strong>{{overview.openAlerts}}</strong><small>需要运营关注</small></article><article><span>用量成本</span><strong>{{money(overview.usageCostMinorUnits)}}</strong><small>模型用量汇总</small></article><article><span>支持授权</span><strong>{{overview.activeSupportGrants}}</strong><small>有效临时授权</small></article></section><section class="operations-grid"><article class="commercial-card"><header><div><span class="eyebrow">TENANT STATE</span><h3>租户与订阅健康</h3></div></header><dl class="commercial-detail-list"><div><dt>订阅覆盖率</dt><dd>{{ratio(overview.activeSubscriptions,overview.activeTenants)}}</dd></div><div><dt>已支付订单</dt><dd>{{overview.paidOrders}}</dd></div><div><dt>开放告警</dt><dd>{{overview.openAlerts}}</dd></div></dl><el-progress :percentage="percentage(overview.activeSubscriptions,overview.activeTenants)" /></article><article class="commercial-card"><header><div><span class="eyebrow">RESOURCE VIEW</span><h3>资源与成本</h3></div></header><dl class="commercial-detail-list"><div><dt>累计模型成本</dt><dd>{{money(overview.usageCostMinorUnits)}}</dd></div><div><dt>有效支持授权</dt><dd>{{overview.activeSupportGrants}}</dd></div><div><dt>异常告警</dt><dd>{{overview.openAlerts}}</dd></div></dl><p class="commercial-hint">该接口只返回聚合指标，不暴露租户敏感配置或成员信息。</p></article><article class="commercial-card"><header><div><span class="eyebrow">SERVICE HEALTH</span><h3>服务健康</h3></div><el-tag :type="health?.status==='UP'?'success':'danger'">{{health?.status??'UNKNOWN'}}</el-tag></header><dl class="commercial-detail-list"><div><dt>服务</dt><dd>{{health?.serviceName??'—'}}</dd></div><div><dt>检查时间</dt><dd>{{health?formatTime(health.checkedAt):'—'}}</dd></div><div><dt>检查方式</dt><dd>基础存活检查</dd></div></dl></article></section></template>
  </div>
</template>

<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'; import { Key } from '@element-plus/icons-vue'; import { commercialApi } from '../api/runtime'; import type { PlatformOverview, SystemStatus } from '../commercial/types'
const platformToken=ref(''); const overview=ref<PlatformOverview>(); const health=ref<SystemStatus>(); const loading=ref(false); const error=ref('')
async function loadHealth(){try{health.value=await commercialApi.systemStatus()}catch{health.value={serviceName:'AI BI API',status:'DOWN',checkedAt:new Date().toISOString()}}} async function loadOverview(){if(!platformToken.value.trim())return;loading.value=true;error.value='';try{overview.value=await commercialApi.platformOverview(platformToken.value.trim());await loadHealth()}catch(e){overview.value=undefined;error.value=e instanceof Error?e.message:'平台身份验证失败'}finally{loading.value=false}} function clearToken(){platformToken.value='';overview.value=undefined;error.value=''} function money(v:number){return new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(v/100)} function percentage(a:number,b:number){return b?Math.min(100,Math.round(a/b*100)):0} function ratio(a:number,b:number){return b?`${a}/${b}（${percentage(a,b)}%）`:'暂无租户'} function formatTime(v:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'medium'}).format(new Date(v))}
void loadHealth();onBeforeUnmount(clearToken)
</script>
